mapper.sql:
case
	when #{levelNo} IN (1, 2)
		then writer_id = #{userId}
	when #{levelNo} = 3
		then writer_id = #{userId}
			or li.status_code = 'PND'
			or (select ah.proc_id from approval_history ah where approval_num = li.num and ah.status_code = 'APR' order by ah.his_num desc limit 1)
				= #{userId}
	when #{levelNo} = 4
		then writer_id = #{userId}
			or li.status_code not in ('TMP', 'PND')
	else 1=1
end
